import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

#ifndef WARP_SIZE
#define WARP_SIZE 32
#endif

template <typename T>
__device__ __forceinline__ float to_float_dev(T v) { return static_cast<float>(v); }

template <typename T>
__device__ __forceinline__ T from_float_dev(float v) { return static_cast<T>(v); }

__device__ __forceinline__ float warp_reduce_sum(float v) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        v += __shfl_down_sync(0xffffffff, v, offset);
    }
    return v;
}

template<int BLOCK_THREADS>
__device__ __forceinline__ float block_reduce_sum(float v) {
    __shared__ float shared[32];
    int lane = threadIdx.x & 31;
    int warp = threadIdx.x >> 5;
    v = warp_reduce_sum(v);
    if (lane == 0) shared[warp] = v;
    __syncthreads();
    v = (threadIdx.x < (BLOCK_THREADS + 31) / 32) ? shared[lane] : 0.0f;
    if (warp == 0) v = warp_reduce_sum(v);
    return v;
}

template <typename scalar_t, int BLOCK_THREADS>
__global__ __launch_bounds__(BLOCK_THREADS, 2)
void layernorm_kernel(const scalar_t* __restrict__ x,
                      const scalar_t* __restrict__ w,
                      const scalar_t* __restrict__ b,
                      scalar_t* __restrict__ y,
                      int64_t rows, int64_t cols, int64_t stride, float eps) {
    int64_t row = blockIdx.x;
    if (row >= rows) return;
    const scalar_t* __restrict__ xr = x + row * stride;
    scalar_t* __restrict__ yr = y + row * stride;

    float sum = 0.0f;
    for (int64_t c = threadIdx.x; c < cols; c += BLOCK_THREADS) {
        sum += to_float_dev(xr[c]);
    }
    sum = block_reduce_sum<BLOCK_THREADS>(sum);
    __shared__ float sm_mean;
    __shared__ float sm_rstd;
    if (threadIdx.x == 0) sm_mean = sum / (float)cols;
    __syncthreads();
    float mean = sm_mean;

    float varsum = 0.0f;
    for (int64_t c = threadIdx.x; c < cols; c += BLOCK_THREADS) {
        float d = to_float_dev(xr[c]) - mean;
        varsum += d * d;
    }
    varsum = block_reduce_sum<BLOCK_THREADS>(varsum);
    if (threadIdx.x == 0) sm_rstd = rsqrtf(varsum / (float)cols + eps);
    __syncthreads();
    float rstd = sm_rstd;

    for (int64_t c = threadIdx.x; c < cols; c += BLOCK_THREADS) {
        float xv = to_float_dev(xr[c]);
        float wv = to_float_dev(w[c]);
        float bv = to_float_dev(b[c]);
        float out = (xv - mean) * rstd * wv + bv;
        yr[c] = from_float_dev<scalar_t>(out);
    }
}

template <typename scalar_t, int BT>
static void launch_ln(const scalar_t* x, const scalar_t* w, const scalar_t* b, scalar_t* y,
                      int64_t rows, int64_t cols, int64_t stride, cudaStream_t stream) {
    dim3 grid(rows);
    layernorm_kernel<scalar_t, BT><<<grid, BT, 0, stream>>>(x, w, b, y, rows, cols, stride, 1.0e-5f);
}

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor w, torch::Tensor b) {
    TORCH_CHECK(x.is_cuda(), "x must be cuda");
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    auto y = torch::empty_like(x);
    int64_t rows = x.size(0);
    int64_t cols = x.size(1);
    int64_t stride = x.stride(0);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    AT_DISPATCH_FLOATING_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, x.scalar_type(), "layernorm_forward_cuda", [&] {
        const scalar_t* xp = x.data_ptr<scalar_t>();
        const scalar_t* wp = w.data_ptr<scalar_t>();
        const scalar_t* bp = b.data_ptr<scalar_t>();
        scalar_t* yp = y.data_ptr<scalar_t>();
        if (cols <= 64) {
            launch_ln<scalar_t, 64>(xp, wp, bp, yp, rows, cols, stride, stream);
        } else if (cols <= 256) {
            launch_ln<scalar_t, 128>(xp, wp, bp, yp, rows, cols, stride, stream);
        } else if (cols <= 1024) {
            launch_ln<scalar_t, 256>(xp, wp, bp, yp, rows, cols, stride, stream);
        } else {
            launch_ln<scalar_t, 256>(xp, wp, bp, yp, rows, cols, stride, stream);
        }
    });
    return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("layernorm_forward", &layernorm_forward, "LayerNorm forward CUDA");
}
