def _get_ext():
    global _ext
    if _ext is None:
        _ext = load_inline(
            name="ln_h100_cuda_ext_v1",
            cpp_sources="",
            cuda_sources=_src,
            functions=None,
            extra_cuda_cflags=["-O3", "--use_fast_math"],
