#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

template <typename T>
__device__ __forceinline__ float to_float_dev(T v) { return static_cast<float>(v); }
template <typename T>
__device__ __forceinline__ T from_float_dev(float v) { return static_cast<T>(v); }

__device__ __forceinline__ float warp_sum(float v) {
    #pragma unroll
    for (int o=16;o>0;o>>=1) v += __shfl_down_sync(0xffffffff, v, o);
    return v;
}

template<int BT>
__device__ __forceinline__ void block_sum2(float &a, float &b) {
    __shared__ float sa[32], sb[32];
    int lane=threadIdx.x&31, warp=threadIdx.x>>5;
    a=warp_sum(a); b=warp_sum(b);
    if(lane==0){sa[warp]=a; sb[warp]=b;}
    __syncthreads();
    int nw=(BT+31)/32;
    a=(threadIdx.x<nw)?sa[lane]:0.f;
    b=(threadIdx.x<nw)?sb[lane]:0.f;
    if(warp==0){a=warp_sum(a); b=warp_sum(b);}    
}

template <typename scalar_t, int BT>
__global__ __launch_bounds__(BT, 2)
void ln_kernel(const scalar_t* __restrict__ x, const scalar_t* __restrict__ w, const scalar_t* __restrict__ b,
               scalar_t* __restrict__ y, int64_t rows, int64_t cols, int64_t stride) {
    int64_t row=blockIdx.x; if(row>=rows) return;
    const scalar_t* xr=x+row*stride; scalar_t* yr=y+row*stride;
    float sum=0.f, sumsq=0.f;
    for(int64_t c=threadIdx.x;c<cols;c+=BT){ float v=to_float_dev(xr[c]); sum+=v; sumsq=fmaf(v,v,sumsq); }
    block_sum2<BT>(sum,sumsq);
    __shared__ float sm_mean, sm_rstd;
    if(threadIdx.x==0){
        float mean=sum/(float)cols;
        float var=fmaxf(sumsq/(float)cols - mean*mean, 0.0f);
        sm_mean=mean; sm_rstd=rsqrtf(var+1.0e-5f);
    }
    __syncthreads();
    float mean=sm_mean, rstd=sm_rstd;
    for(int64_t c=threadIdx.x;c<cols;c+=BT){
        float xv=to_float_dev(xr[c]);
        float out=(xv-mean)*rstd*to_float_dev(w[c])+to_float_dev(b[c]);
        yr[c]=from_float_dev<scalar_t>(out);
    }
}

